query:
mutation networkConfigDnsUpdateSuffixSet ( $accountId:ID! $networkConfigDnsUpdateSuffixSetInput:NetworkConfigDnsUpdateSuffixSetInput!) {
	networkConfig ( accountId:$accountId ) {
		dns {
			updateSuffixSet ( input:$networkConfigDnsUpdateSuffixSetInput   ) {
				dnsSuffixSet {
					id
					name
					suffix
					audit {
						updatedTime
						updatedBy {
							id
							name
							... on AdminRef {
							}
							... on ApiKeyRef {
							}
						}
					}
				}
			}
		}
	}	
}
